\begin{align*}
\iderr(\cA,\cD,\cC,n)&=\E\bigl[\err_\cD(\cA(S))\bigr]-\inf_{L\in\cC}\err_\cD(L),\\
\generr(\cA,\cD,\cC,n)&=\Pr\bigl[\cA(S)\notin\supp(\cD)\setminus S\bigr],
\end{align*}
where $S\sim\cD^n$ and the randomness of $\cA$ is independent of $S$.

